P<-normalizePath('ccRCC_signature_transportability_benchmark_2026');W<-file.path(P,'84_JCO_PO_Upgrade_20261113');O<-file.path(W,'05_analysis/B1_operator_panel_trials');source(file.path(W,'05_analysis/shared/operators.R'));library(survival)
a<-readRDS(file.path(P,'37_A_clinical_workflow_validation_20260917/local_only/INPUTS.rds'));fold<-readRDS(file.path(P,'37_A_clinical_workflow_validation_20260917/local_only/FOLD_ASSIGNMENTS.rds'));rows<-list();fr<-list();cx<-list()
for(tr in names(a)){d<-a[[tr]]$d;for(sig in c('Angio16','Angio36')){x<-a[[tr]]$M[[sig]];g<-rownames(x);s0<-O1(x,g)$scores;s1<-O2(x,g)$scores;n<-ncol(x);dis<-sum((s0>=median(s0))!=(s1>=median(s1)));rows[[length(rows)+1]]<-data.frame(trial=tr,signature=sig,n=n,disagreement_n=dis,disagreement_pct=100*dis/n,check=if(sig=='Angio36')dis==if(tr=='JAVELIN')48 else 80 else TRUE)
for(re in 1:5){h0<-h1<-rep(NA,n);for(f in 1:5){ix<-which(fold[[tr]][[re]]!=f);it<-which(fold[[tr]][[re]]==f);b0<-O1(x,g,ix)$scores;b1<-O2(x,g,ix)$scores;h0[it]<-b0[it]>=median(b0[ix]);h1[it]<-b1[it]>=median(b1[ix])};fr[[length(fr)+1]]<-data.frame(trial=tr,signature=sig,partition=re,n=n,disagreement_n=sum(h0!=h1),disagreement_pct=100*mean(h0!=h1))}
for(op in c('O1','O2')){dd<-d;dd$v<-get(op)(x,g)$scores;dd$a<-O2(a[[tr]]$M$APM12,rownames(a[[tr]]$M$APM12))$scores;stopifnot(max(abs(dd$a-dd$APM12_z))<1e-8);fit<-coxph(Surv(time,event)~v+a+trt+v:trt+a:trt,data=dd,ties='efron',control=coxph.control(eps=1e-10,iter.max=50));b<-summary(fit)$coefficients['v:trt',];cx[[length(cx)+1]]<-data.frame(trial=tr,signature=sig,operator=op,HR=exp(b[1]),low=exp(b[1]-1.96*b[3]),high=exp(b[1]+1.96*b[3]),p=b[5])}
}}
rr<-do.call(rbind,rows);ff<-do.call(rbind,fr);cc<-do.call(rbind,cx);write.csv(rr,file.path(O,'results/reproduction_full.csv'),row.names=FALSE);write.csv(ff,file.path(O,'results/reproduction_frozen.csv'),row.names=FALSE);write.csv(cc,file.path(O,'results/reproduction_interaction.csv'),row.names=FALSE);print(rr);print(ff);print(cc);stopifnot(all(rr$check));for(tr in names(a)){f<-subset(ff,trial==tr&signature=='Angio36');expected<-if(tr=='JAVELIN')c(5.79,7.44)else c(9.72,10.33);stopifnot(max(abs(round(range(f$disagreement_pct),2)-expected))<1e-8)}
e<-c(1.53,1.52,1.32,1.43);actual<-cc$HR[cc$operator=='O1'];stopifnot(all(abs(actual-e)<.015));stopifnot(abs(subset(cc,trial=='IMmotion151'&signature=='Angio36'&operator=='O1')$HR-1.4270)<.0001,abs(subset(cc,trial=='IMmotion151'&signature=='Angio36'&operator=='O2')$HR-1.4272)<.0001);cat('PASS ALL reproduction gates\n')
